      '<button onclick="opsAddDailyRow(\'' + block + '\')" style="margin-top:3px;font-size:11px;padding:2px 10px;border:.5px solid var(--bdr2);border-radius:20px;background:var(--bg);cursor:pointer;color:var(--tx2)">+ γραμμή</button>';
  }
  const imatismosBlock = '<div style="flex:1;min-width:190px">' +
    '<div style="font-size:13px;font-weight:700;color:#1a1a2e;margin:0 0 5px">Ιματισμός</div>' +
    subTable('Χολαργός', 'imatismos_cholargos', 1) +
    subTable('Θεσσαλονίκη', 'imatismos_thess', 1) +
    '</div>';
  const dailyBlocks = '<div style="display:flex;gap:20px;flex-wrap:wrap;margin-top:18px;max-width:900px">' +
    blockTable('Ρεπό', 'repo', 5) +
    blockTable('Άδειες', 'adeies', 5) +
    blockTable('Οδηγοί / Μεταφορείς', 'odigoi', 2) +
    imatismosBlock +
    '</div>';

  return '<div style="margin-top:22px" id="ops-cleaning-table">' + datalist +
    '<div id="ops-cleaning-shot" style="background:#fff;padding:4px 2px 8px">' +
    '<div style="display:flex;align-items:center;gap:10px;margin-bottom:6px;flex-wrap:wrap">' +
    '<div style="font-size:14px;font-weight:700;color:#1a1a2e">Καθαρισμοί σήμερα <span id="ops-clean-count" style="font-size:11px;font-weight:400;color:#9CA3AF">(' + doneCount + '/' + clean.length + ' έτοιμα)</span></div>' +
    '<button onclick="opsManageCleaners()" title="Add or remove cleaners" style="font-size:11px;padding:3px 10px;border:.5px solid var(--bdr2);border-radius:20px;background:var(--bg);cursor:pointer;color:var(--tx2)">Καθαρίστριες</button>' +
    '<button onclick="opsCopyCleaningImage()" title="Copy this table as an image — paste into chat" style="font-size:11px;padding:3px 10px;border:.5px solid #7C3AED;border-radius:20px;background:var(--bg);cursor:pointer;color:#7C3AED">Screenshot</button>' +
    '</div>' +
    '<table style="width:100%;max-width:760px;border-collapse:collapse;font-size:13px">' +
    '<thead><tr style="background:#F3F4F6">' +
    '<th style="padding:6px 6px;border:1px solid #E5E7EB;text-align:center;width:34px">✓</th>' +
    '<th style="padding:6px 10px;border:1px solid #E5E7EB;text-align:left">Κατάλυμα</th>' +
    '<th style="padding:6px 10px;border:1px solid #E5E7EB;text-align:left">Καθαρίστρια</th>' +
    '<th style="padding:6px 10px;border:1px solid #E5E7EB;text-align:left">Εργασία</th>' +
    '<th style="padding:6px 10px;border:1px solid #E5E7EB;text-align:left">Σημείωση</th>' +
    '</tr></thead><tbody>' + body + '</tbody></table>' +
    '</div>' +
    dailyBlocks +
    '</div>';
}
